import { useState } from "react";
import ClientsList from "../Components/ClientsList/ClientsList";
import Clients from "../Components/Clients/Clients";

const ClientsPage = () => {
  const [selectedClient, setSelectedClient] = useState(null);

  const clients = [
    {
      id: 1,
      name: "Cliente 1",
      area: "Auditoría",
      invoice: "00001010929",
      total: 1500,
    },
    {
      id: 2,
      name: "Cliente 2",
      area: "Fiscal",
      invoice: "00001010930",
      total: 2500,
    },
  ];

  return (
    <div className="container">
      <ClientsList
        clients={clients}
        onSelectClient={setSelectedClient}
      />

      <Clients
        client={selectedClient}
      />
    </div>
  );

    const ClientsList = ({ clients, onSelectClient }) => {
  return (
    <div>
      {clients.map((client) => (
        <div
          key={client.id}
          onClick={() => onSelectClient(client)}
          className="client-card"
        >
          {client.name}
        </div>
      ))}
    </div>
  );
};

const Clients = ({ client }) => {
  if (!client) {
    return <div>Selecciona un cliente</div>;
  }

  return (
    <div>
      <h1>{client.name}</h1>

      <p>
        <strong>Área:</strong> {client.area}
      </p>

      <p>
        <strong>Invoice:</strong> {client.invoice}
      </p>

      <p>
        <strong>Total:</strong> {client.total}
      </p>
    </div>
  );
};

};

export default ClientsPage;
